-- 0356 PROD CHECK (before), read-only, ONE statement: npx --yes supabase@2.120.0 db query --linked -f scripts/ops/harness/reputation/level-before-hunks.sql
-- Wanted: 4 rows; every old_times 1 and new_times 0; made 0 (no marks table, function or knob of 0356 yet); r1 "true/10" (reputation_on and rep_lap,
-- R1's, as 0352 left them); head 20260818000355 (0354 and 0355 deploy first; neither cuts one of these four texts).
-- Generated by scripts/ops/harness/reputation/gen-level-checks.mjs from the migration's own hunks. Only the catalog and two world_config keys are read.
begin transaction read only;
with h(fn, ord, old, new) as (values
  ('public.reputation_arrival(uuid,uuid)'::text, 1, $h$  select v.total_nm, v.dest_port_id, v.departed_at into v_nm, v_dest, v_sailed
$h$, $h$  -- 0356 (R4): every level she has crossed and not been paid for fires here, at the arrival's own moment (public.level_marks_settle)
  perform public.level_marks_settle(p_player);
  select v.total_nm, v.dest_port_id, v.departed_at into v_nm, v_dest, v_sailed
$h$),
  ('public.reputation_card(uuid)'::text, 1, $h$    'seq',     coalesce(b.seq, 0),
$h$, $h$    'seq',     coalesce(b.seq, 0),
    -- 0356 (R4): the level of each track whose crossing was paid (no row counts as 1), and the gift a level: level L pays level_gift x L
    'level_marks', (select jsonb_build_object(
                      'trading',     coalesce(max(m.level) filter (where m.track = 'trading'), 1),
                      'exploration', coalesce(max(m.level) filter (where m.track = 'exploration'), 1),
                      'combat',      coalesce(max(m.level) filter (where m.track = 'combat'), 1))
                      from public.house_level_marks m where m.player_id = p_player),
    'level_gift', public.wc_int('rep_level_per_level'),
$h$),
  ('cmd.standing_route_close_lap(uuid,timestamp with time zone)'::text, 1, $h$    'skipped', jsonb_array_length(l.skipped), 'skipped_lines', l.skipped));
$h$, $h$    'skipped', jsonb_array_length(l.skipped), 'skipped_lines', l.skipped));
  -- 0356 (R4): a lap closed at a gain earns Reputation, once a lap (public.reputation_lap: no gain returns before any read; a merchant after one players probe)
  perform public.reputation_lap(sr.player_id, l.id, l.net, sr.name, l.lap_no);
$h$),
  ('public.client_rpc_entry_points()'::text, 1, $h$      ('world',       'levels',                ''),
$h$, $h$      ('world',       'levels',                ''),
      -- 0356: the caller's level crossings paid (public.level_marks_settle). No argument, no player id.
      ('cmd',         'level_up',              ''),
$h$)
), d as (
  select h.*, replace(pg_get_functiondef(h.fn::regprocedure), chr(13), '') as def from h
)
select fn, ord,
       (length(def) - length(replace(def, old, ''))) / length(old) as old_times,
       (length(def) - length(replace(def, new, ''))) / length(new) as new_times,
       (select count(*) from pg_class c where c.oid = to_regclass('public.house_level_marks'))
         + (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace
             where (n.nspname, p.proname) in (('public', 'level_marks_settle'), ('cmd', 'level_up'), ('public', 'reputation_lap')))
         + (select count(*) from public.world_config c where c.key = 'rep_level_per_level') as made,
       (select c.value::text from public.world_config c where c.key = 'reputation_on') || '/' || (select c.value::text from public.world_config c where c.key = 'rep_lap') as r1,
       (select max(version) from supabase_migrations.schema_migrations) as head
  from d order by fn, ord;
commit;
